return {api_version=1,id="EX1_059",name="Crazed Alchemist",text="<b>Battlecry:</b> Swap the Attack and Health of a minion.",set="EXPERT1",type="minion",rarity="rare",cost=2,attack=2,health=2,tags={"undead"},keywords={"battlecry"},target_mode="required_if_available",targets=function(ctx)return ctx:minions()end,on_battlecry=function(ctx,self,target)if target then local e=ctx:entity(target);cardlib.effects.modify(ctx, target,{stat="attack",operation="set",value=e.health});ctx:set_health(target,e.attack)end end}
